import{_ as o,l as s,o as e,c as A,v as l,p as i,x as t,d as n,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"学习率：LoRA 对全参","description":"","frontmatter":{"title":"学习率：LoRA 对全参","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lora-vs-full-lr.md","filePath":"llm/lora-vs-full-lr.md","lastUpdated":1789023840000}'),m={name:"llm/lora-vs-full-lr.md"};function d(L,a,E,B,f,c){const r=s("Mermaid");return e(),A("div",null,[a[1]||(a[1]=l('<h1 id="学习率-lora-对全参" tabindex="-1">学习率：LoRA 对全参 <a class="header-anchor" href="#学习率-lora-对全参" aria-label="Permalink to &quot;学习率：LoRA 对全参&quot;">​</a></h1><div class="epigraph"><p>同一套指令、同一个优化器，LoRA 常用 $10^{-4}$ 量级，全参常用 $10^{-5}$；把其中一个数字抄到另一种参数化上，是 SFT 最常见的事故。</p><footer>—— 对照 Hu 等 LoRA（2021）与 Llama 2 / InstructGPT 的全参 SFT 实践；Biderman 等 LoRA Learns Less and Forgets Less（2024）给出遗忘差异</footer></div><p><a href="/llm/neftune">NEFTune</a>是正则，不改变「能走多大步」。缺口在参数化：<a href="/llm/lora">LoRA</a> 的 \\(\\Delta W=BA\\) 从零起步、还有 \\(\\alpha/r\\) 缩放；<a href="/llm/full-sft-hparams">全参 SFT</a> 动已经学好的 \\(W_0\\)，步子必须小。工程上却经常共用一份 YAML。本课把两条学习率标成<strong>不可互换的默认</strong>，并说明为何 LoRA 忘得少、学得也少。不把长上下文显存（<a href="/llm/long-context-finetune">下一课</a>）混进 \\(\\eta\\) 网格。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全参更新是 \\(W\\leftarrow W-\\eta\\nabla_W\\mathcal{L}\\)，每一步直接改预训练特征。\\(\\eta\\) 取预训练峰值（常 \\(10^{-4}\\)）会在短指令上把底层投影打歪，指令损失很好、通用能力先掉——<a href="/llm/full-sft-hparams">全参课</a>已写。LoRA 的可训练对象是 \\(A,B\\)，有效权重变化还乘 \\(\\alpha/r\\)（或 rsLoRA 的 \\(1/\\sqrt{r}\\)）。同一数值 \\(\\eta\\) 作用在不同对象上，位移的物理单位不同。</p><p>抄错有两种。把全参的 \\(2\\times 10^{-5}\\) 用在 LoRA：适配器几乎不动，看起来像数据不行。把 LoRA 的 \\(1\\times 10^{-4}\\) 到 \\(2\\times 10^{-4}\\) 用在全参：一轮即可过拟合并遗忘。QLoRA 冻结 4-bit 基座，学习率跟 LoRA 走，不跟全参走。</p><h3 id="有效步长含缩放-不含「感觉」" tabindex="-1">有效步长含缩放，不含「感觉」 <a class="header-anchor" href="#有效步长含缩放-不含「感觉」" aria-label="Permalink to &quot;有效步长含缩放，不含「感觉」&quot;">​</a></h3><p>LoRA 前向是 \\(y=W_0x+\\frac{\\alpha}{r}BAx\\)。对 \\(A\\) 的梯度含 \\(B\\) 与 \\(\\alpha/r\\)，对 \\(B\\) 的梯度含 \\(A\\) 与 \\(\\alpha/r\\)。\\(\\eta\\)、\\(\\alpha\\)、\\(r\\) 三个旋钮乘在同一条增量上。只扫 \\(\\eta\\)、把 \\(\\alpha\\) 当魔法常数，网格不可迁。全参没有 \\(\\alpha\\)，只有 \\(\\eta\\) 与调度。</p><p><span class="marginnote">Biderman 等人 2024 年比较 LoRA 与全参：LoRA 在指令上往往学得不足，同时在源域上忘得也少。学习率不能单独「补上」学得不足——加大 \\(\\eta\\) 会先破坏低秩子空间的稳定性，而不是变成全参轨迹。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两条出发点分开写进配方。</p><p>全参：峰值 \\(\\eta\\) 约预训练的 \\(1/10\\)–\\(1/20\\)，7B–70B 常见 \\(1\\times 10^{-5}\\)–\\(5\\times 10^{-5}\\)；短预热、余弦；有效批次按 token 做大；1–3 epoch。详见<a href="/llm/full-sft-hparams">全参超参</a>。</p><p>LoRA：\\(\\eta\\) 常见 \\(1\\times 10^{-4}\\)–\\(3\\times 10^{-4}\\)（视 \\(\\alpha/r\\) 而定）；嵌入与 LM head 若全参训练则用更小的 \\(\\eta\\) 或单独分组；适配器 dropout 可选。\\(r\\) 增大时若仍用 \\(\\alpha/r\\)，有效更新变小，有人提高 \\(\\eta\\) 补偿，有人改缩放（<a href="/llm/rslora">rsLoRA</a> 课）。不要用全参的线性缩放规则去乘 LoRA 的 \\(\\eta\\)。</p>',13)),(e(),i(h,null,{default:t(()=>[p(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E5%90%8C%E4%B8%80%E6%8C%87%E4%BB%A4%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20F%5B%22%E5%85%A8%E5%8F%82%EF%BC%9A%E5%B0%8F%20%CE%B7%EF%BC%8C%E5%8A%A8%20W0%22%5D%0A%20%20D%20--%3E%20L%5B%22LoRA%EF%BC%9A%E8%BE%83%E5%A4%A7%20%CE%B7%EF%BC%8C%E5%8A%A8%20A%2CB%22%5D%0A%20%20F%20--%3E%20NF%5B%22%E5%BF%98%E5%BE%97%E5%A4%9A%EF%BC%8C%E8%A1%A8%E8%BE%BE%E5%8A%9B%E4%B8%8A%E9%99%90%E9%AB%98%22%5D%0A%20%20L%20--%3E%20NL%5B%22%E5%BF%98%E5%BE%97%E5%B0%91%EF%BC%8C%E5%8F%97%E7%A7%A9%E5%A4%A9%E8%8A%B1%E6%9D%BF%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>分组学习率：同一模型里 LoRA 模块与解冻的范数/头可以不同 \\(\\eta\\)。混用时日志分别打梯度范数。数据谱系不改变分叉：ShareGPT 与 FLAN 都要选对参数化对应的 \\(\\eta\\)，脏数据时全参更危险。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LoRA 初始化 \\(BA=0\\)，早期梯度只在低秩因子上积累。大学习率把因子拉到有用的子空间，而不直接旋转 \\(W_0\\) 的主轴，所以源域特征更稳。全参没有这条「从零增量」的缓冲，小 \\(\\eta\\) 是在限制 \\(\\|\\Delta W\\|\\) 的每步幅度。</p><p>遗忘与学习率的关系因此不对称。全参大学习率沿高秩方向改表示，灾难性遗忘显著。LoRA 再大，更新仍落在 \\(r\\) 维里，忘不了那么多，也改不了那么多——这是表达力，不是免费正则。任务需要满秩更新时，应加 \\(r\\) 或改全参，而不是把 LoRA 的 \\(\\eta\\) 加到发散。</p><p><span class="marginnote"><a href="/llm/chat-template">chat template</a> 与仅回复掩码错误时，两种参数化都会「变傻」。先排除格式，再比较 η。用错误掩码扫出的「最优学习率」不可用。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>DoRA、AdaLoRA 有自己的几何与秩分配，默认 \\(\\eta\\) 不能从本课直接抄，但「适配器大于全参」的方向仍在。嵌入层若解冻，应对齐全参量级，否则词表漂移。长上下文 SFT 有效批次更小，应先补累积，再动 \\(\\eta\\)，见<a href="/llm/long-context-finetune">下一课</a>。</p><p>验证两张表：指令遵循与源域保持。LoRA 选点常在「源域几乎不掉、指令略欠」；全参选点常在「指令更满、源域开始掉」。没有一张表上的单一最优 \\(\\eta\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LoRA 与全参的学习率默认差约一个数量级，不可共用一份配置。</li><li>LoRA 的有效步长还含 \\(\\alpha/r\\)；改 \\(r\\) 必须重看 \\(\\eta\\)。</li><li>全参步子过大导致遗忘；LoRA 步子过小导致学不动，过大则过拟合适配器。</li><li>Biderman 等：LoRA 往往学得少、忘得少；加大 \\(\\eta\\) 不能把它变成全参。</li><li>QLoRA 跟 LoRA 的 \\(\\eta\\)，不跟全参。</li><li>出处：Hu 等，LoRA，2021；Touvron 等，Llama 2，2023；Biderman 等，LoRA Learns Less and Forgets Less，2024。</li></ul>',10))])}const _=o(m,[["render",d]]);export{R as __pageData,_ as default};
